(()=>{'use strict';const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],KEY='finsyndeo-approved-platform-2026-10-07'+(new URLSearchParams(location.search).get('admin_tour')==='1'?'-admin-training':''),M=DeltaModel,IM=IntroducerModel,W=ApprovedWorkflows,clone=x=>JSON.parse(JSON.stringify(x)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={bank:'Business bank account',merchant:'Merchant account',both:'Bank & merchant accounts',financing:'Financing',individual:'Private banking',institution:'Correspondent / payment accounts'},services={bank:'business_bank',merchant:'merchant_acquiring',both:'bank_and_merchant',financing:'business_financing',individual:'private_banking',institution:'correspondent_payment'},families={bank:'bank',merchant:'merchant',both:'both',financing:'finance',individual:'private',institution:'correspondent'},introServices={bank:'Bank account',merchant:'Merchant account',both:'Both bank and merchant accounts',financing:'Financing',individual:'Private banking',institution:'Correspondent accounts'};
const navs={applicant:[['home','Dashboard'],['start','Find a Provider'],['cases','My assessments'],['results','Results & introductions'],['alerts','Match notifications'],['sharing','Sharing permissions'],['privacy','Account & data']],provider:[['home','Dashboard'],['profile','Institution Apply'],['preferences','Reporting preferences'],['reports','Case reports'],['privacy','Account & data']],introducer:[['home','Dashboard'],['invited-login','Invited sign-in'],['referrals','My referrals'],['ledger','Commission ledger'],['invoice','Upload invoice'],['invoices','Payments & reconciliation'],['documents','My Documents'],['privacy','Account & data']],admin:[['home','Overview'],['cases','Prospects & assessments'],['diligence','Due diligence & client file'],['catalogue','Providers & approvals'],['provider-terms','Provider commercial terms'],['matching','Matching criteria'],['intro-overview','Introducer overview & tiers'],['intro-profiles','Introducers'],['intro-providers','Introducer provider access'],['intro-referrals','Clients & relationships'],['intro-commissions','Provider commissions'],['intro-invoices','Invoices & payments'],['intro-reports','Accounting reports'],['settings','Introduction & pricing'],['entitlements','Entitlements & decisions'],['reportsettings','Report controls'],['ratings','External ratings'],['payment-ledger','Applicant payment ledger'],['notifications','Notification history'],['audit','Introduction audit trail'],['intro-audit','Introducer audit trail'],['systemaudit','Platform activity']]};
let state;try{state=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}if(!state?.version)state=seed();W.initialise(state);for(const p of state.financial.providers)if(!state.publishedProfiles[p.id])state.publishedProfiles[p.id]=FinSyndeoMatching.fixtureProfile(p);const requestedReferral=new URLSearchParams(location.search).get('ref');if(requestedReferral){const intro=new IM.Store(state.intro),person=intro.s.introducers.find(i=>i.token===requestedReferral);if(person&&intro.linkActive(person.id)){state.pendingReferral={token:person.token,introId:person.id,onBehalf:false,authority:false};state.role=null;state.screen='home';}}let frameToken='',frameContext=null,waitingSample=false,pendingAction=null;const frame=q('#module');
function seed(){const financial=M.seed(),intro=IM.seed();financial.requests=[];financial.payments=[];financial.notifications=[];for(const p of financial.providers){p.active=true;p.exampleRoutes=Object.keys(labels);p.exampleCurrencies=p.id==='P26'?['EUR','GBP','CHF']:['EUR','GBP','USD','CHF'];p.exampleMinDeposit=p.id==='P26'?500000:50000;let ip=intro.providers.find(i=>i.id===p.code);if(!ip){ip={id:p.code,name:p.name,eligible:p.introEligible,reporting:p.clientCommissionReporting,frequency:'Monthly',taxDefault:'manual',currency:'EUR',approved:true,overrides:{},services:[...Object.values(introServices),'Bank account','Merchant account']};intro.providers.push(ip);}p.introEligible=ip.eligible;p.introReporting=ip.reporting;p.clientCommissionReporting=ip.reporting;p.introOverrides=clone(ip.overrides);}
return {version:1,role:null,screen:'home',seq:0,cases:[],active:null,financial,intro,providerId:'P14',providerDrafts:{},publishedProfiles:Object.fromEntries(financial.providers.map(p=>[p.id,FinSyndeoMatching.fixtureProfile(p)])),providerSubmissions:{},introDrafts:{},meetings:[],chat:[],events:[],email:'client@review.example',pendingReferral:null};}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{message('Browser storage is full. Export this review before adding more documents.',true);}}
function message(text,error=false){q('#feedback').hidden=false;q('#feedback').className=error?'error':'';q('#feedback').textContent=text;}
function event(action,record,detail){state.events.push({at:new Date().toISOString(),actor:state.role,action,record,detail});}
function button(action,text,data='',primary=false){return `<button type="button" data-action="${action}" ${data} class="${primary?'primary':''}">${esc(text)}</button>`;}
function head(title,lead=''){return `<div class="hero"><h1>${esc(title)}</h1>${lead?`<p class="lead">${esc(lead)}</p>`:''}</div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td data-label="${esc(headers[i])}"><span>${v}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function getCase(){return state.cases.find(c=>c.id===state.active);}
function selectCase(){return state.cases.length?`<label class="field"><span>Assessment</span><select id="case-choice">${state.cases.map(c=>`<option value="${c.id}" ${c.id===state.active?'selected':''}>${esc(c.name||'Draft assessment')} · ${esc(labels[c.route])}</option>`).join('')}</select></label>`:'';}
function sampleChoices(){return `<div class="button-row">${Object.entries(labels).map(([route,label])=>button('sample',label,`data-route="${route}"`)).join('')}</div>`;}
function loginPage(){return head('Welcome to FinSyndeo','Find a financial institution or manage your institution’s provider profile.')+`<form id="login-form" class="panel"><div class="checks"><label class="service-card"><input type="radio" name="login-role" value="applicant" checked><span><b>I am looking for a provider</b><small>Banking, merchant accounts, financing and correspondent facilities.</small></span></label><label class="service-card"><input type="radio" name="login-role" value="provider"><span><b>I am a financial institution</b><small>I offer facilities and want to be included in your list of providers.</small></span></label></div><label class="field" style="margin-top:20px"><span>Email address</span><input type="email" id="sign-email" value="${esc(state.email)}" required></label><button class="primary">Continue in review mode</button><p class="screen-note">Sign-in is simulated. Use a fictional email. Invited introducers and SOPHIMA are accessible through “Review another role”.</p></form>`;}
function dashboard(){const role=state.role;if(role==='provider')return head('Your institution workspace','Manage facilities, acceptance criteria and reports in your provider account.')+`<div class="tiles">${[['Your profile','Services, industries, countries, authorisations and internal documents.','profile'],['Reporting preferences','Automatic reporting periods and ad hoc reports.','preferences'],['Case reports','Only your authorised provider relationships.','reports']].map(([title,text,screen])=>`<section class="tile"><h2>${title}</h2><p>${text}</p>${button('nav','Open','data-screen="'+screen+'"')}</section>`).join('')}</div><p class="notice">Updated criteria require SOPHIMA review before publication. The last approved version remains active during review.</p>`;
if(role==='admin')return head('SOPHIMA overview','Prospects, providers, introductions, due diligence and accounting.')+`<div class="stat-row"><div><b>${state.cases.length}</b><span>Assessments</span></div><div><b>${state.cases.filter(c=>!c.reviewed).length}</b><span>Awaiting review</span></div><div><b>${state.financial.requests.length}</b><span>Introduction requests</span></div></div><div class="tiles">${[['Prospect files','Review screening scope, ownership and business activities.','diligence'],['Providers','Verify referral agreements and provider criteria.','catalogue'],['Introducers','Agreements, referrals, commissions and invoices.','intro-profiles']].map(([title,text,screen])=>`<section class="tile"><h2>${title}</h2><p>${text}</p>${button('nav','Open','data-screen="'+screen+'"')}</section>`).join('')}</div><section class="panel"><h2>Explore all applicant journeys</h2>${sampleChoices()}</section>`;
return head('Your FinSyndeo dashboard','Assessments, potential providers and introductions in one place.')+`<div class="tiles">${[['Find a Provider','One adaptive questionnaire for your needs.','start'],['Your assessments','Resume, edit or review saved applications.','cases']].map(([title,text,screen])=>`<section class="tile"><h2>${title}</h2><p>${text}</p>${button('nav','Open','data-screen="'+screen+'"')}</section>`).join('')}</div><details class="sample-actions"><summary>Explore complete fictional applications</summary><p>Each button creates a separate example; your other assessments are retained.</p>${sampleChoices()}<div class="button-row">${button('fourth','Try the fourth-introduction payment')}</div></details>`;}
function startPage(){return head('Tell us about your needs','Choose how you would like to share them.')+`<div class="tiles"><section class="tile"><h2>Questionnaire</h2><p>Bank, merchant, both, financing, private banking or correspondent accounts.</p>${button('new','Start questionnaire','',true)}</section><section class="tile"><h2>Guided intake</h2><p>Spoken prompts and typed answers. Prototype: no live AI.</p>${button('nav','Start conversation','data-screen="assistant"')}</section></div>`;}
function casesPage(){return head(state.role==='admin'?'Prospects & assessments':'My assessments','Keep drafts, edit answers and review results.')+(state.cases.length?state.cases.map(c=>`<section class="case-card"><div class="case-top"><div><h2>${esc(c.name||'Draft assessment')}</h2><p>${esc(labels[c.route])} · ${c.id}</p></div><span class="pill">${c.submitted?c.reviewed?'Reviewed in sample':'Awaiting SOPHIMA review':'Draft'}</span></div><p class="hint">${c.referral?'Attributed to '+esc(c.referral.introId)+(c.referral.onBehalf&&!c.applicantConfirmed?' · applicant confirmation required':''):'Direct application'}${c.sample?' · fictional example':''}</p><div class="button-row">${button('edit-case','Edit assessment',`data-id="${c.id}"`)}${c.submitted?button('case-results','View results',`data-id="${c.id}"`,true):''}${state.role==='admin'?button('case-dd','Review file',`data-id="${c.id}"`):''}${c.referral?.onBehalf&&!c.applicantConfirmed&&state.role==='applicant'?button('confirm-applicant','Confirm my referred application',`data-id="${c.id}"`):''}</div></section>`).join(''):'<div class="empty">No assessments yet. Start a questionnaire or load a fictional example.</div>')+`<div class="button-row">${button('new','Start a new assessment','',true)}</div>`;}
function fieldRows(c){return (c.assessment?.sections||[]).flatMap(s=>s.fields.map(f=>({...f,section:s.title})));}
function dossier(){const c=getCase();if(!c)return head('Due diligence & client file')+'<p>Complete an assessment or load an example from the overview.</p>';return head('Due diligence & client file','Internal SOPHIMA review. No live screening or document transmission is connected.')+selectCase()+`<section class="panel"><h2>${esc(c.name)}</h2><dl class="case-details"><dt>Application</dt><dd>${c.id} · ${esc(labels[c.route])}</dd><dt>Jurisdiction / residence</dt><dd>${esc(c.assessment.jurisdiction)}</dd><dt>Registration</dt><dd>${esc(c.assessment.registration||'Individual')}</dd><dt>Review</dt><dd>${c.reviewed?'Cleared by recorded sample review':'Unverified — introduction held'}</dd><dt>Evidence status</dt><dd>Screening feeds, registries and website verification are not connected. Absence of a sample hit does not establish clearance.</dd></dl></section><section class="panel"><h2>Screening scope</h2>${table(['Subject','Relationship','Screening status'],[[esc(c.name),'Applicant','Not live-screened'],...W.subjects(c).filter(p=>p.role!=='Applicant').map(p=>[esc(p.name),esc(p.role)+' · '+esc(p.source),'Not checked'])])}<p class="hint">Relevant named persons, entities and counterparties are mapped to lawful screening scopes. Country exposure is assessed separately. Undeclared affiliates and unavailable registry records remain coverage limitations.</p></section><section class="panel"><h2>Business activities & website</h2><dl class="case-details"><dt>Declared activity</dt><dd>${esc(c.assessment.activity||'Not applicable to this route')}</dd><dt>Website</dt><dd>${esc(c.assessment.website||'Not provided')}</dd><dt>Website comparison</dt><dd>Not fetched. The production report must cite sources and compare declared and observed activities.</dd><dt>Licensing</dt><dd>${c.assessment.licenseRequired?'Verify licence number, holder, regulator, scope and current validity.':'No licence declared / applicability requires review.'}</dd></dl></section><section class="panel"><h2>Ownership & related entities</h2><ul class="tree"><li><span>${esc(c.name)}</span><ul>${(c.assessment.persons||[]).filter(p=>p.name).map(p=>`<li><span>${esc(p.name)} · ${p.percentage?esc(p.percentage)+'%':'Control entry'}<br><small>${esc(p.nationalities.join(', '))} · resident ${esc(p.residence)}</small></span></li>`).join('')||'<li><span>Review declared ownership / control information below.</span></li>'}</ul></li></ul><p class="hint">Registry-derived links and other companies connected to UBOs remain unverified until evidence is obtained.</p></section><section class="panel"><h2>Complete declared profile</h2>${(c.assessment.sections||[]).map(s=>`<details><summary>${esc(s.title)}</summary><dl class="case-details">${s.fields.map(f=>`<dt>${esc(f.label)}</dt><dd>${esc(f.value)}</dd>`).join('')}</dl></details>`).join('')}</section><form id="dd-form" class="panel"><h2>Review decision</h2><label class="field"><span>Decision</span><select id="dd-status"><option value="hold" ${!c.reviewed?'selected':''}>Hold — further verification needed</option><option value="clear" ${c.reviewed?'selected':''}>Clear for prototype introduction</option><option value="block">Block under sample SOPHIMA policy</option></select></label><label class="checkline"><input id="dd-evidence" type="checkbox" required> This is a fictional review decision, not a live screening result.</label><label class="field"><span>Review reason / evidence reference</span><textarea id="dd-reason" required></textarea></label><button class="primary">Record sample decision</button></form><section class="panel"><h2>Institution client file</h2><p>Applicant profile, questionnaire, ownership and document checklist. The internal due-diligence report stays separate.</p><label class="field"><span>Institution for authorised export</span><select id="share-provider">${state.financial.providers.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><p>Applicant approval must be recorded for this institution and current revision in Sharing permissions. Admin cannot approve on the applicant’s behalf.</p><div class="button-row">${button('download-dd','Download internal review report')}${button('download-file','Prepare institution client file')}${button('nav','Introduction / provider decision','data-screen="entitlements"')}</div><p class="hint">Current clearance and applicant confirmation are required. Missing evidence stays explicitly marked.</p></section>`;}
function catalogue(){return head('Providers & approvals','A changed draft does not replace approved matching criteria until SOPHIMA approves it.')+state.financial.providers.map(p=>`<section class="case-card"><div class="provider-row"><h2>${esc(p.name)} · ${esc(p.code)}</h2><span class="pill">${p.active?'Available':'Paused'}</span></div><p class="hint">${state.providerSubmissions[p.id]?'Profile awaiting SOPHIMA review':'Illustrative published profile'}</p><div class="button-row">${button('provider-profile','Review profile',`data-id="${p.id}"`)}${button('provider-active',p.active?'Pause listing':'Activate sample listing',`data-id="${p.id}"`)}${state.providerSubmissions[p.id]?button('approve-provider','Approve submitted profile',`data-id="${p.id}"`):''}</div></section>`).join('')+`<form id="provider-approval" hidden class="panel"><h2>Verify before listing</h2><label class="checkline"><input id="agreement-ok" type="checkbox" required> Signed referral agreement verified in the sample</label><label class="checkline"><input id="licence-ok" type="checkbox" required> Authorisation, services and acceptance criteria reviewed in the sample</label><label class="field"><span>Review reference</span><input id="approval-reason" required></label><button class="primary">Publish approved profile</button></form>`;}
function matchingPage(){const c=getCase();return head('Matching criteria','Essential eligibility comes before preference ranking. Fees and commissions do not improve fit.')+selectCase()+`<section class="panel"><p>Every applicable declared requirement is evaluated against versioned provider criteria. Alternative products are evaluated separately. Unknown support remains conditional and cannot qualify as an eligible result.</p><p>Fit describes supported preferences. Coverage shows how much applicable information is confirmed. Neither is a probability of approval.</p></section>`+(c?table(['Provider','Eligibility','Preference fit','Coverage','Reason'],state.financial.providers.map(p=>{const m=state.financial.matches.find(m=>m.app===c.app&&m.provider===p.id);return [esc(p.code),m?.essential?'Eligible':m?.conditional?'Conditional':'Unavailable',m?.score==null?'Not scored':esc(m.score)+'%',esc(m?.coverage??0)+'%',esc(m?.reason||'Complete assessment first')];})):'<p>Select a completed assessment.</p>');}
function meetingPage(){return startPage();}
const prompts=['What is the registered company name, or your name and surname for private banking?','In which country is the applicant incorporated, or resident for private banking?','Describe your activity and the facilities you need.'];
function assistantPage(){const g=state.guided;return head('Guided intake','Choose your request, then answer the prompts. You will confirm every field in the questionnaire.')+`<section class="panel"><p class="notice">This prototype reads English prompts aloud and accepts typed answers. Live AI and microphone input are not connected.</p>${!g.route?`<div class="checks">${Object.entries(labels).map(([route,label])=>button('guided-route',label,`data-route="${route}"`)).join('')}</div>`:`<h2>${esc(labels[g.route])}</h2><div class="chat-log">${g.answers.map((m,i)=>`<div class="bubble">${esc(prompts[i])}</div><div class="bubble user">${esc(m)}</div>`).join('')}<div class="bubble">${esc(prompts[g.answers.length]||'Complete and confirm your questionnaire.')}</div></div>${g.answers.length<3?`<div class="button-row"><button type="button" id="read-prompt">Read prompt aloud</button><button type="button" id="stop-prompt">Stop audio</button></div><p id="voice-status" role="status"></p><form id="chat-form"><label class="field"><span>Your answer</span><input id="chat-answer" required minlength="2"></label><button class="primary">Save answer</button></form>`:button('chat-profile',g.caseId?'Resume my questionnaire':'Continue in questionnaire','',true)}<div class="button-row">${button('guided-reset','Start a new guided intake')}</div>`}</section>`;}
function coverage(){return head('What is connected?','All approved modules are accessible in one workspace. External integrations remain simulated.')+table(['Facility','Available for review','Production integration'],[['Applicant','Six questionnaires, saved drafts, editing, final summary','Verified access and server storage'],['Results','Sorting, comparisons, introductions, alert thresholds','Provider database and full matcher'],['Payment','Quotas, checkout, outcomes, receipt and ledger','Gateway, tax / invoices'],['Provider','Profiles, policy uploads, approval and reports','Protected storage, extraction and delivery'],['Introducer','Link, full referred form, authority, agreement, commissions and invoices','Verified invited access and receipt feeds'],['SOPHIMA','DD scope, ownership tree, client file and all controls','Registry, sanctions, PEP, media, licensing and website evidence'],['Intake','Explicit service selection, spoken English prompts and typed answers','Verified AI voice service and shared questionnaire schema']])+`<p class="notice">A consolidated review prototype. This is the single entry for reviewing the platform as a whole.</p>`;}
function module(path,init){frameContext={path,...init};frame.dataset.ready='no';frameToken=crypto.randomUUID();frame.name='whole-platform:'+JSON.stringify({...init,token:frameToken});q('#content').hidden=true;frame.hidden=false;frame.src=path+'?whole_review_token='+encodeURIComponent(frameToken);}
function application(c,sample=false){module('modules/application/FinSyndeo-review.html',{kind:'application',role:'applicant',email:state.email,route:c.route,draft:c.assessment?.draft||null,fresh:!c.assessment?.draft,sample,fourth:c.fourthDemo,caseId:c.id});}
function billing(view){const c=getCase();if(state.role==='applicant'&&!c?.submitted){q('#content').innerHTML=head('Complete an assessment first','Choose a saved assessment or load a fictional example to explore results and payments.')+sampleChoices();return;}const role=state.role==='admin'?'admin':state.role==='provider'?'provider':'applicant';module('modules/facilities/Platform-preview.html',{kind:'facilities',role,actor:role==='admin'?'SOPHIMA':role==='provider'?state.providerId:c.client,application:c?.app,financial:state.financial,view,provider:state.providerId});}
function introducer(view){module('modules/introducer/Introducer-module.html',{kind:'introducer',role:state.role==='admin'?'admin':'introducer',introId:'I-A',view,intro:state.intro,drafts:state.introDrafts});}
function activityPage(){return head('Platform activity','Prototype history, automated email drafts and privacy requests.')+table(['When','Actor','Action','Record'],state.events.slice().reverse().map(e=>[esc(e.at),esc(e.actor),esc(e.action),esc(e.record)]))+`<section class="panel"><h2>Email outbox</h2><p>Drafted automatically from validated sample events. No email service is connected.</p>${state.outbox.map(m=>`<details><summary>${esc(m.template)} · ${esc(m.subject)} · ${esc(m.status)}</summary><p>To: ${esc(m.to.join(', '))}</p><p>Case revision: ${m.caseRevision} · template ${esc(m.templateVersion)}</p><p>${esc(m.body)}</p><p>Idempotency key: ${esc(m.idempotencyKey)}</p></details>`).join('')||'<p>No draft events yet.</p>'}</section><section class="panel"><h2>Privacy requests</h2>${table(['Request','Applicant','Received','Status'],state.privacyRequests.map(r=>[esc(r.kind),esc(r.requestedBy),esc(r.requestedAt),esc(r.status)]))}<p>Production must verify identity and record deletion/retention outcomes and processor or recipient notices. The prototype records requests only.</p></section>`;}
function privacyPage(){return head('Account & data','Manage your information, applications and notification preferences.')+`<section class="panel"><h2>How your information is used</h2><p>SOPHIMA acts as an introducer. Your information is used to assess declared requirements, identify potential providers, prepare checks and arrange an introduction you authorise.</p><p>Before an introduction, you choose the institution and approve the recipient, purpose and current profile revision. Internal due-diligence findings and provider policy documents are not included in the client profile.</p><p>Processing bases depend on the purpose: requested services, documented legitimate interests, and consent where required. Optional alerts and voice recording are separate choices. Declining them does not prevent using the questionnaire.</p><p>Raw audio is not retained by default. Closed files and inactive drafts are reviewed after 90 days under the proposed operational schedule. Minimal accounting or dispute records may have a different justified retention period. The production retention schedule must name the applicable basis and duration.</p><p>You may request access, correction, restriction, objection, portability where applicable, and erasure. Erasure is subject to lawful exceptions and is not an immediate deletion of every accounting record. A response is normally due within one month.</p><div class="button-row">${button('export-my-data','Download my prototype information')}${button('disable-alerts','Turn off future-provider alerts')}</div></section>${state.role==='applicant'?selectCase()+`<section class="panel"><h2>Application and account controls</h2><p>Withdrawing an application stops new introductions and its alerts. An erasure request closes activity and starts a review of the records that may lawfully need to be retained.</p><div class="button-row">${button('withdraw-case','Withdraw selected application')}${button('request-erasure','Request account and data deletion')}</div></section>`:''}<section class="panel"><h2>Your requests</h2>${table(['Request','Date','Status'],state.privacyRequests.filter(r=>r.requestedBy===state.email).map(r=>[esc(r.kind),esc(r.requestedAt),esc(r.status)]))}</section><p class="notice">These are local demonstrations. Production must provide secure identity verification, rights handling, recipient correction notices and deletion of server, processor and backup copies under the approved schedule.</p>`;}
function sharingPage(){const c=getCase();if(!c?.submitted)return head('Sharing permissions','Complete and confirm an assessment first.');const requested=state.financial.requests.filter(r=>r.app===c.app).map(r=>r.provider),providers=state.financial.providers.filter(p=>requested.includes(p.id));return head('Approve an institution introduction','Check the named institution and recipient before sharing the current client profile.')+selectCase()+(!providers.length?'<p>Request an introduction from Results & introductions first. No sharing has been authorised.</p>':`<form id="sharing-form" class="panel"><label class="field"><span>Selected institution</span><select id="sharing-provider">${providers.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label class="field"><span>Verified institution recipient — fictional example</span><input id="sharing-recipient" type="email" value="introductions@provider.review.example" required></label><p>Application ${esc(c.id)} · profile revision ${c.revision}. Purpose: assess this requested introduction. Your questionnaire and authorised client profile may be supplied. The internal due-diligence report and provider documents are excluded.</p><label class="checkline"><input id="sharing-confirm" type="checkbox" required>I authorise SOPHIMA to share this profile revision with the named institution and recipient for this introduction.</label><button class="primary">Record my sample approval</button></form>`)+table(['Institution','Profile revision','Recipient','Status'],(c.sharingApprovals||[]).map(a=>[esc(a.institution),esc(a.revision),esc(a.recipient),a.withdrawnAt?'Withdrawn':'Applicant approved']));}
function render(){save();q('#feedback').hidden=true;document.body.classList.toggle('signed-out',!state.role);q('#sidebar').hidden=!state.role;q('#sign-out').hidden=!state.role;q('#persona').innerHTML=state.role?`<b>${esc({applicant:'Applicant workspace',provider:'Provider workspace',introducer:'Introducer workspace',admin:'SOPHIMA Admin'}[state.role])}</b>${esc(state.role==='provider'?state.financial.providers.find(p=>p.id===state.providerId).code:state.role==='introducer'?'Alex Morgan · approved introducer':state.role==='admin'?'Internal review account':state.email)}`:'';q('#nav').innerHTML=state.role?navs[state.role].map(([s,label])=>`<button data-action="nav" data-screen="${s}" ${state.screen===s?'aria-current="page"':''}>${label}</button>`).join(''):'';if(state.role==='admin'){const groups={home:'Daily operations',catalogue:'Providers and matching','intro-overview':'Introducers and accounting',settings:'Controls and notifications',audit:'Audit history'};q('#nav').innerHTML=navs.admin.map(([id,label])=>(groups[id]?`<p class="nav-group">${groups[id]}</p>`:'')+`<button data-action="nav" data-screen="${id}" ${state.screen===id?'aria-current="page"':''}>${label}</button>`).join('');}q('#content').hidden=false;frame.hidden=true;frame.src='about:blank';frameContext=null;const s=state.screen;if(!state.role){q('#content').innerHTML=loginPage();bind();return;}if(s==='invited-login'&&state.role==='introducer'){introducer('login');return;}if(s==='home'&&state.role==='introducer'){introducer('dashboard');return;}if(['referrals','ledger','invoice','invoices','documents'].includes(s)&&state.role==='introducer'){introducer(s);return;}if(s.startsWith('intro-')){introducer(s.slice(6));return;}if(s==='questionnaire'){application(getCase(),waitingSample);waitingSample=false;return;}if(s==='profile'){module('modules/application/Institution-apply.html',{kind:'provider',role:'provider',email:'institution@review.example',draft:state.providerDrafts[state.providerId]||providerExample(state.providerId),fresh:false,providerId:state.providerId});return;}const bill={'provider-terms':'providers',results:'results',alerts:'alerts',preferences:'preferences',reports:'reports',settings:'settings',entitlements:'entitlements',reportsettings:'reportsettings',ratings:'ratings','payment-ledger':'ledger',notifications:'notifications',audit:'audit'};if(bill[s]){billing(bill[s]);return;}const screens={home:dashboard,start:startPage,cases:casesPage,diligence:dossier,catalogue,matching:matchingPage,privacy:privacyPage,sharing:sharingPage,assistant:assistantPage,systemaudit:activityPage,coverage};q('#content').innerHTML=(screens[s]||dashboard)();bind();}
function go(screen){document.body.classList.remove('menu-open');state.screen=screen;render();window.scrollTo(0,0);}
function newCase(route='bank',sample=false){state.role='applicant';const c={id:'CASE-'+(++state.seq),route,name:'',sample,submitted:false,reviewed:false,applicantConfirmed:true,referral:state.pendingReferral?clone(state.pendingReferral):null};state.pendingReferral=null;if(c.referral?.onBehalf)c.applicantConfirmed=false;state.cases.push(c);state.active=c.id;waitingSample=sample;event('Assessment created',c.id,{route,sample});go('questionnaire');}
function providerExample(id){const p=state.financial.providers.find(p=>p.id===id),f=FinSyndeoMatching.fixtureProfile(p);return {...f,step:0,current:f.offers[0].id,core:{...f.core,registration:'SAMPLE-'+p.code,type:'Bank',website:'https://example.com',founded:'2010',contactName:'Sam Example',contactEmail:'institution@review.example',contactRole:'Authorised representative',referralChannel:'Secure portal',authority:true,accuracy:true},licenses:[{id:'sample-licence',data:{status:'Authorised / licensed',holder:p.name,authority:'Example regulator',country:p.country,scope:'Banking and payment services',number:'SAMPLE-'+p.code,register:'https://example.com'}}],admin:{availability:{}}};}
function syncIntro(){const is=new IM.Store(state.intro);is.login('admin','SOPHIMA Admin');for(const p of state.financial.providers){const ip=is.s.providers.find(i=>i.id===p.code);if(ip){p.introEligible=ip.eligible;p.introReporting=ip.reporting;p.clientCommissionReporting=ip.reporting;p.introOverrides=clone(ip.overrides);}}for(const r of state.financial.requests){const c=state.cases.find(c=>c.app===r.app);if(!c?.introApplication||!r.introducedDate)continue;const p=state.financial.providers.find(p=>p.id===r.provider),wanted=c.route==='both'?['Bank account','Merchant account']:[introServices[c.route]];for(const service of wanted){let rel=is.s.relationships.find(x=>x.application===c.introApplication&&x.provider===p.code&&x.service===service);try{if(!rel){const id=is.createRelationship(c.introApplication,p.code,service);rel=is.s.relationships.find(x=>x.id===id);}if(['Matching Completed','Introduction Requested'].includes(rel.status))is.setRelationship(rel.id,'Introduced',true);}catch(e){event('Introducer relationship held',c.id,e.message);}}}state.intro=is.s;}
function updateFinancial(c){const st=new M.Store(state.financial);st.login('admin','SOPHIMA');const identity=c.route==='individual'?'person:'+c.assessment.email:'entity:'+c.assessment.jurisdiction+':'+c.assessment.registration;let client=st.s.clients.find(x=>x.identity===identity);if(!client){client=st.enrolFixture('CLIENT-'+c.id,c.name);client.identity=identity;client.intro=c.referral?.introId||null;}else if(client.intro!==(c.referral?.introId||null))throw Error('Existing client attribution differs. SOPHIMA must review; attribution has not changed.');c.client=client.id;c.app=c.app||'ASSESS-'+c.id;let a=st.s.apps.find(a=>a.id===c.app);if(!a){a={...clone(st.s.apps.find(a=>a.id==='APP-'+client.id)),id:c.app};st.s.apps.push(a);}a.demoFixture=false;a.service=services[c.route];a.confirmed=c.applicantConfirmed;a.dd=!!c.reviewed;a.blocked=!!c.blocked;a.feedFresh=true;a.simulation=true;a.sharingApprovals=clone(c.sharingApprovals||[]);a.confirmedIdentity=state.email===c.assessment.email&&c.applicantConfirmed;a.revision=c.revision||1;a.alerts=a.alerts||{enabled:false,threshold:90};state.financial=st.s;refreshMatches(c);for(const p of state.financial.providers)if(!state.financial.eligibilitySeen.some(e=>e.app===c.app&&e.provider===p.id)){const s=new M.Store(state.financial);s.login('admin','SOPHIMA');state.financial.eligibilitySeen.push({app:c.app,provider:p.id,eligible:!!s.eligible(c.app,p)});}}
const industries=['Agriculture & food production','Construction & engineering','Consulting & professional services','Crypto-asset services — exchange, custody or brokerage','E-commerce & retail','Education & training','Energy & utilities','Financial services & fintech','Forex brokerage & CFD dealing','Healthcare & pharmaceuticals','Holding & investment companies','Hospitality & tourism','Import, export & wholesale trade','Manufacturing','Marketing, media & entertainment','Gambling & betting — real-money wagering','Real estate','Shipping, transport & logistics','Software, IT & telecommunications','Video games & esports — no gambling or wagering','Blockchain / crypto software development — no customer asset services','Other','Adult industry'];
function evaluateNotifications(){const s=new M.Store(state.financial);s.login('admin','SOPHIMA');s.evaluateAlerts();s.deliverAlerts();state.financial=s.s;}
function refreshMatches(c){if(!c.app)return;state.financial.matches=state.financial.matches.filter(m=>m.app!==c.app);const result=FinSyndeoMatching.evaluate(c.assessment,state.financial.providers,state.publishedProfiles,{now:new Date().toISOString()});c.matching=result;for(const m of result.matches)state.financial.matches.push({...m,app:c.app,provider:typeof m.provider==='object'?m.provider.id:m.provider,revision:c.revision||1});}
function submit(c,assessment){c.assessment=assessment;c.name=assessment.name;c.route=assessment.route;c.submitted=true;if(!c.referral?.onBehalf)c.applicantConfirmed=true;c.revision=c.revision||1;c.sharingApprovals||=[];W.queue(state,c,'E02',assessment.email,'Your request is saved. Review the confirmed declaration in your FinSyndeo account. No institution has approved this application.');const is=new IM.Store(state.intro);if(c.referral&&!c.introApplication){is.login(c.referral.onBehalf?'introducer':'applicant',c.referral.onBehalf?c.referral.introId:assessment.email);c.introApplication=is.submitReferral(c.referral.token,{type:c.route==='individual'?'individual':c.route==='institution'?'financial_institution':'entity',name:c.name,country:assessment.jurisdiction,registration:c.route==='individual'?'':assessment.registration,email:assessment.email,service:introServices[c.route],needs:assessment.needs,onBehalf:c.referral.onBehalf,authority:c.referral.authority,terms:true,privacy:true});state.intro=is.s;}updateFinancial(c);if(c.fourthDemo&&!c.fourthPrepared){const st=new M.Store(state.financial);st.login('admin','SOPHIMA');const previous=st.s.settings.nonremCharge;st.settings({nonremCharge:false},'Historical fourth-introduction sample: earlier free terms');for(const pid of ['P14','P26','P21']){st.login('applicant',c.client);const id=st.request(c.app,pid,true);st.login('admin','SOPHIMA');const hist=st.s.apps.find(x=>x.id===c.app);hist.demoFixture=true;st.decide(id,'approve','Explicit historical fictional fixture — not applicant consent');hist.demoFixture=false;}st.settings({nonremCharge:previous},'Restore current terms after historical sample fixture');state.financial=st.s;c.fourthPrepared=true;}event('Assessment confirmed',c.id,{revision:c.revision,referral:c.referral?.introId});save();go('results');}
function bind(){q('#sharing-form')?.addEventListener('submit',e=>{e.preventDefault();const c=getCase(),p=state.financial.providers.find(p=>p.id===q('#sharing-provider').value);W.approve(state,c,p,q('#sharing-recipient').value);updateFinancial(c);event('Applicant sharing approval',c.id,{provider:p.id,revision:c.revision});render();message('Sample approval recorded. No profile was sent.');});q('#read-prompt')?.addEventListener('click',()=>{if(!window.speechSynthesis){q('#voice-status').textContent='Read-aloud unavailable in this browser.';return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(prompts[state.guided.answers.length]||'Review your questionnaire.');u.lang='en-GB';u.rate=1.1;speechSynthesis.speak(u);q('#voice-status').textContent='Reading question. Answers are typed; microphone and AI are not connected.';});q('#stop-prompt')?.addEventListener('click',()=>speechSynthesis.cancel());q('#login-form')?.addEventListener('submit',e=>{e.preventDefault();state.email=q('#sign-email').value;state.role=q('[name=login-role]:checked').value;if(state.pendingReferral&&state.role==='applicant')newCase();else go('home');message('Review account opened. No sign-in email was sent.');});q('#case-choice')?.addEventListener('change',e=>{state.active=e.target.value;render();});q('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();state.guided.answers.push(q('#chat-answer').value.trim());render();});q('#dd-form')?.addEventListener('submit',e=>{e.preventDefault();const c=getCase(),decision=q('#dd-status').value;c.reviewed=decision==='clear';c.blocked=decision==='block';c.review={decision,reason:q('#dd-reason').value,at:new Date().toISOString(),basis:'Fictional manual review; no live screening'};updateFinancial(c);const a=state.intro.applications.find(a=>a.id===c.introApplication);if(a)a.ddClear=c.reviewed;event('Due diligence sample decision',c.id,c.review);render();message('Review decision recorded.');});q('#provider-approval')?.addEventListener('submit',e=>{e.preventDefault();const id=q('#provider-approval').dataset.provider;state.publishedProfiles[id]={...clone(state.providerSubmissions[id]),approvalStatus:'approved',version:(state.publishedProfiles[id]?.version||0)+1,effectiveAt:new Date().toISOString(),reviewBy:new Date(Date.now()+90*86400000).toISOString(),approvalReference:q('#approval-reason').value};delete state.providerSubmissions[id];const p=state.financial.providers.find(p=>p.id===id);p.approved=p.agreement=true;/* Existing Admin availability is preserved. */event('Provider criteria published in sample',id,q('#approval-reason').value);for(const c of state.cases.filter(c=>c.submitted))refreshMatches(c);evaluateNotifications();render();message('Profile approved in the sample. Matches were refreshed from its declared criteria.');});}
function download(name,body,type='text/html'){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function file(c,internal){return W.document(c,internal);}
function action(a,b){if(a==='nav')go(b.dataset.screen);else if(a==='new')newCase();else if(a==='sample')newCase(b.dataset.route,true);else if(a==='fourth'){newCase('bank',false);getCase().sample=true;getCase().fourthDemo=true;waitingSample=true;render();}else if(['edit-case','case-results','case-dd'].includes(a)){state.active=b.dataset.id;go(a==='edit-case'?'questionnaire':a==='case-dd'?'diligence':'results');}else if(a==='provider-profile'){state.providerId=b.dataset.id;go('profile');}else if(a==='provider-active'){const p=state.financial.providers.find(p=>p.id===b.dataset.id);if(!p.active&&(!p.approved||!p.agreement))throw Error('Verify authorisation and referral agreement before activation.');p.active=!p.active;event('Provider availability changed',p.id,p.active);for(const c of state.cases.filter(c=>c.submitted))refreshMatches(c);evaluateNotifications();render();}else if(a==='approve-provider'){const f=q('#provider-approval');f.hidden=false;f.dataset.provider=b.dataset.id;f.scrollIntoView({behavior:'smooth'});}else if(a==='download-dd')download(getCase().id+'-internal-review.html',file(getCase(),true));else if(a==='download-file'){const c=getCase();if(!c.reviewed||c.blocked||!c.applicantConfirmed)throw Error('Current SOPHIMA clearance and applicant confirmation are required.');if(!W.approval(c,q('#share-provider').value))throw Error('The applicant must approve this institution, recipient and current profile revision first.');event('Authorised client profile prepared',c.id,{revision:c.revision});save();download(c.id+'-institution-file.html',file(c,false));}else if(a==='confirm-applicant'){const c=state.cases.find(c=>c.id===b.dataset.id),is=new IM.Store(state.intro);if(state.email.toLowerCase()!==c.assessment.email.toLowerCase())throw Error('Sign in as the applicant to confirm this application.');is.loginApplicantDemo(state.email);is.confirmApplicant(c.introApplication,c.assessment.email,true,true);state.intro=is.s;c.applicantConfirmed=true;updateFinancial(c);render();message('Applicant confirmation recorded in this review account.');}else if(a==='guided-route'){state.guided={route:b.dataset.route,answers:[],caseId:null};render();}else if(a==='guided-reset'){state.guided={route:null,answers:[],caseId:null};render();}else if(a==='chat-profile'){const g=state.guided;if(g.caseId&&state.cases.some(c=>c.id===g.caseId)){state.active=g.caseId;go('questionnaire');return;}const values=g.answers.slice(),route=g.route;if(!Object.hasOwn(labels,route))throw Error('Choose a service first.');newCase(route);g.caseId=getCase().id;frameContext.prefill={'company-name':values[0],'pb-name':values[0]?.split(' ')[0],'pb-first-name':values[0]?.split(' ')[0],'pb-surname':values[0]?.split(' ').slice(1).join(' '),'incorporation':values[1],'pb-residence':values[1],'activity':values[2]};}else if(a==='export-my-data'){const mine=state.role==='applicant'?{account:state.email,cases:state.cases.filter(c=>c.assessment?.email===state.email),privacyRequests:state.privacyRequests.filter(r=>r.requestedBy===state.email)}:state.role==='provider'?{profile:state.providerDrafts[state.providerId],publishedProfile:state.publishedProfiles[state.providerId]}:{introducer:state.intro.introducers.find(i=>i.id==='I-A'),agreements:state.intro.documents?.filter(d=>d.introducer==='I-A')};download('FinSyndeo-my-data.json',JSON.stringify(mine,null,2),'application/json');}else if(a==='disable-alerts'){for(const app of state.financial.apps)if(state.cases.some(c=>c.app===app.id&&c.assessment?.email===state.email))app.alerts.enabled=false;render();message('Future-provider alerts are disabled.');}else if(a==='withdraw-case'){const c=getCase();if(!c)throw Error('Select an assessment first.');W.request(state,'Withdraw application',c);event('Application withdrawn',c.id);render();}else if(a==='request-erasure'){W.request(state,'Delete account and personal data');event('Erasure requested',state.email);render();message('Prototype erasure request recorded. Retention exceptions require review; no production server data exists in this prototype.');}}

function run(fn){try{fn();save();}catch(e){message(e.message,true);}}
function afterFlush(fn){if(frameContext?.initialized&&!frame.hidden){pendingAction=fn;send('snapshot');}else run(fn);}
q('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)afterFlush(()=>action(b.dataset.action,b));});q('#content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)afterFlush(()=>action(b.dataset.action,b));});q('#switch-role').onclick=()=>q('#role-dialog').showModal();q('#close-roles').onclick=()=>q('#role-dialog').close();all('[data-role]').forEach(b=>b.onclick=()=>{afterFlush(()=>{state.role=b.dataset.role;q('#role-dialog').close();go('home');});});q('#sign-out').onclick=()=>afterFlush(()=>{state.role=null;go('home');});q('#coverage-link').onclick=()=>{if(!state.role)state.role='applicant';go('coverage');};q('#export-review').onclick=()=>download('FinSyndeo-prototype-records.json',JSON.stringify(state,null,2),'application/json');q('#reset-review').onclick=()=>{if(!confirm('Reset only this complete review? Its drafts, sample documents and changes will be removed. Earlier packages remain unchanged.'))return;state=seed();render();};
function send(action,data={}){if(frameContext)frame.contentWindow.postMessage({channel:'whole-platform-v1',token:frameToken,action,...data},'*');}
window.addEventListener('message',e=>{const m=e.data;if(!frameContext||e.source!==frame.contentWindow||m?.channel!=='whole-platform-v1'||m.token!==frameToken)return;run(()=>{if(m.type!=='ready'&&!frameContext.initialized)return;if(m.type==='height')frame.style.height=Math.max(350,Math.min(30000,m.height))+'px';else if(m.type==='ready'){if(!m.initialized){send('initialize',{init:{...frameContext,token:frameToken,initialized:true}});return;}frameContext.initialized=true;frame.dataset.ready='yes';if(frameContext.prefill)send('prefill',{values:frameContext.prefill});}else if(m.type==='draft'){const c=state.cases.find(c=>c.id===frameContext.caseId);if(!c)return;const changed=c.assessment&&JSON.stringify(c.assessment.typed||c.assessment.sections)!==JSON.stringify(m.assessment.typed||m.assessment.sections);c.assessment=m.assessment;c.name=m.assessment.name||c.name;c.route=m.assessment.route||c.route;if(changed){W.invalidate(c,'Application fields changed');c.applicantConfirmed=false;}if(changed&&c.submitted){c.revision=(c.revision||1)+1;const app=state.financial.apps.find(a=>a.id===c.app);if(app){app.dd=false;app.confirmed=false;app.revision=c.revision;}}}else if(m.type==='sample-loaded'){const c=state.cases.find(c=>c.id===frameContext.caseId);c.assessment=m.assessment;c.name=m.assessment.name;c.route=m.assessment.route;c.reviewed=!!m.valid;c.review={decision:m.valid?'clear':'hold',reason:'Preloaded fictional example; no live checks',at:new Date().toISOString()};if(!m.valid)message('This sample needs additional information before confirmation.',true);}else if(m.type==='submitted'){submit(getCase(),m.assessment);}else if(m.type==='financial'){const previous=state.financial.requests.filter(r=>r.introducedDate).map(r=>r.id);state.financial=m.financial;syncIntro();for(const r of state.financial.requests.filter(r=>r.introducedDate&&!previous.includes(r.id))){const c=state.cases.find(c=>c.app===r.app),p=state.financial.providers.find(p=>p.id===r.provider),a=c&&W.approval(c,p.id);if(c&&a)W.queue(state,c,'E09',a.recipient,'Applicant-authorised introduction for '+c.name+'; service '+labels[c.route]+'. Access the approved client profile through the secure production portal. Prototype only; no file sent.','introduction');}}else if(m.type==='intro'){state.intro=m.intro;state.introDrafts=m.drafts;syncIntro();}else if(m.type==='provider'){state.providerDrafts[frameContext.providerId]=m.draft;}else if(m.type==='provider-submitted'){state.providerDrafts[frameContext.providerId]=m.draft;state.providerSubmissions[frameContext.providerId]=clone(m.draft);event('Provider profile submitted',frameContext.providerId);message('Profile submitted for SOPHIMA review. Published criteria are unchanged.');}else if(m.type==='referral-start'){if(m.onBehalf&&!confirm('For this fictional example, confirm you are authorised by the applicant. Evidence must be available to SOPHIMA. Applicant confirmation is required before introduction.'))return;state.pendingReferral={token:m.referralToken,introId:m.introId,onBehalf:m.onBehalf,authority:m.onBehalf};state.role='applicant';newCase();}else if(m.type==='navigate')go(m.screen);else if(m.type==='error')message(m.message,true);if(pendingAction&&['draft','financial','intro','provider','error'].includes(m.type)){const fn=pendingAction;pendingAction=null;fn();}});});
q('#mobile-menu').onclick=()=>document.body.classList.toggle('menu-open');
window.PlatformReview={get state(){return state;},render,go,newCase,send,providerExample,submit,refreshMatches};const tour=new URLSearchParams(location.search).get('admin_tour');if(tour==='1'){state.role='admin';state.screen='home';}window.addEventListener('message',e=>{if(tour!=='1'||e.source!==parent||e.data?.channel!=='finsyndeo-admin-tour')return;if(e.data.action==='sample'&&Object.keys(labels).includes(e.data.route)){afterFlush(()=>newCase(e.data.route,true));return;}const screen=e.data.screen;if(navs.admin.some(([id])=>id===screen)){afterFlush(()=>{state.role='admin';go(screen);});}});render();
})();
